<script setup lang="ts">
import {ref,watch,nextTick,onMounted,onBeforeUnmount} from 'vue';
import {ui} from '../web/platform';
defineOptions({inheritAttrs:false});
const props=defineProps<{open:boolean;title:string;wide?:boolean;left?:boolean;triggerSelector:string}>();
const emit=defineEmits(['close']);
const panel=ref<HTMLElement>();
const height=ref(window.visualViewport?.height||window.innerHeight),top=ref(0);
function Resize(){height.value=window.visualViewport?.height||window.innerHeight;top.value=window.visualViewport?.offsetTop||0;}
let previous:HTMLElement|null=null;
function Keys(event:KeyboardEvent){
  if(!props.open||ui.dialog||ui.preview||document.querySelector('dialog[open]'))return;
  if(event.key==='Escape'){event.preventDefault();const nested=[...panel.value!.querySelectorAll<HTMLElement>('.sheet-mask')].filter(mask=>mask.getClientRects().length).at(-1);if(nested)nested.click();else emit('close');}
}
function Outside(event:PointerEvent){
  const target=event.target as Element;
  if(!props.open||ui.dialog||ui.preview||document.querySelector('dialog[open]')||panel.value?.contains(target)||target.closest(props.triggerSelector))return;
  event.preventDefault();event.stopPropagation();emit('close');
}
watch(()=>props.open,async open=>{if(open){previous=document.activeElement as HTMLElement;await nextTick();if(!props.open||!panel.value)return;panel.value.focus();document.addEventListener('keydown',Keys);document.addEventListener('pointerdown',Outside,true);}else{document.removeEventListener('keydown',Keys);document.removeEventListener('pointerdown',Outside,true);previous?.focus();}},{immediate:true});
onMounted(()=>window.visualViewport?.addEventListener('resize',Resize));
onBeforeUnmount(()=>{document.removeEventListener('keydown',Keys);document.removeEventListener('pointerdown',Outside,true);window.visualViewport?.removeEventListener('resize',Resize);previous?.focus();});
</script>
<template><Teleport to="body"><div v-show="open" class="floating-mask" :class="{'floating-left':left,'floating-wide-mask':wide}" :style="{'--floating-height':height+'px',height:height+'px',top:top+'px'}" @click.self="emit('close')"><section ref="panel" v-bind="$attrs" class="floating-panel" :class="{'floating-wide':wide}" role="dialog" aria-modal="false" :aria-label="title" tabindex="-1"><header class="floating-heading"><h2>{{title}}</h2></header><div class="floating-content"><slot /></div></section></div></Teleport></template>
