ent .workspace-kind,.floating-content .shortcut-hint{display:none}.floating-content .library-meta{flex-wrap:wrap}.floating-content .web-picker{min-width:0}.floating-content .sheet .history-list{max-height:50dvh}@media(min-width:900px){.floating-left{justify-content:flex-start;padding:16px 16px 16px 80px}.floating-wide-mask{padding-bottom:calc(var(--nn-tabs-height) + 16px)}.floating-wide{height:min(780px,calc(var(--floating-height,100dvh) - var(--nn-tabs-height) - 32px))}.notebook-tool-window{width:400px}}@media(max-width:899px){.floating-mask{padding:12px 68px 12px 12px;align-items:center}.floating-left{justify-content:flex-start;padding:12px 12px 12px 68px}.floating-panel{width:min(480px,100%);height:calc(var(--floating-height,100dvh) - 24px);border-radius:20px}.floating-content .page{padding:16px}.floating-content .work-session{margin:0 12px;gap:4px}.floating-content .work-session .quiet-button{padding:0 4px;font-size:12px}.floating-content .thread-content{padding:20px 16px}.floating-content .work-composer{padding:8px 10px calc(12px + env(safe-area-inset-bottom))}.floating-content .compose-box{padding:10px 8px 6px}.floating-content .compose-tools{gap:4px}.floating-heading{padding:14px 16px}.floating-content .prompt-suggestions button{gap:8px}.floating-content .composer-meta{gap:4px;font-size:10px}.floating-content .composer-meta button{font-size:10px}}
